def extract_text_from_docx(docx_path):
    try:
        with zipfile.ZipFile(docx_path) as z:
            xml_content = z.read('word/document.xml').decode('utf-8', errors='ignore')
            text = re.sub(r'<[^>]+>', ' ', xml_content)
            return text
    except:
        return ''

def search_files():
    hits = []
    for sdir in search_dirs:
        if not os.path.exists(sdir):
            continue
        for root, dirs, files in os.walk(sdir):
            if 'node_modules' in root or '.git' in root or '.next' in root:
                continue
            for f in files:
                p = os.path.join(root, f)
                ext = os.path.splitext(f)[1].lower()
                text = ''
                if ext in ['.txt', '.md', '.json', '.html']:
                    try:
                        with open(p, 'r', encoding='utf-8', errors='ignore') as fl:
                            text = fl.read()
                    except:
                        pass
                elif ext == '.docx':
                    text = extract_text_from_docx(p)

                if text:
                    text_lower = text.lower()
                    # Check for combinations of the user's specific concept
                    has_consul = 'consul' in text_lower or 'embajad' in text_lower
                    has_coste = 'sin coste' in text_lower or 'sin costo' in text_lower or 'coste adicional' in text_lower
                    has_apoyo = 'apoyo' in text_lower and ('artista' in text_lower or 'artistas' in text_lower)
                    has_nulo = 'nulo' in text_lower or 'falta de presupuesto' in text_lower or 'historicamente' in text_lower or 'históricamente' in text_lower

                    score = 0
                    if has_consul and has_coste:
                        score += 50
                    if has_consul and has_apoyo:
                        score += 30
                    if has_coste and has_apoyo:
                        score += 40
                    if has_nulo and has_apoyo:
                        score += 30

                    if score >= 60:
                        hits.append((score, p, text[:300]))

    hits.sort(key=lambda x: x[0], reverse=True)
    print(f'Total high-score matches found: {len(hits)}')
    for score, path, snippet in hits[:15]:
        print(f'=== SCORE {score} ===')
        print('FILE:', path)
        # find where matches appear
        try:
            with open(path, 'r', encoding='utf-8', errors='ignore') as fl:
                t = fl.read()
        except:
            t = extract_text_from_docx(path)
        # find snippet around 'coste' or 'consul' or 'apoyo'
        idx = -1
        for w in ['sin coste', 'coste adicional', 'sin costo', 'apoyo']:
            idx = t.lower().find(w)
            if idx != -1:
                break
        if idx != -1:
            start = max(0, idx - 150)
            end = min(len(t), idx + 350)
            print('SNIPPET:\n' + t[start:end].replace('\n', ' '))
        print('-'*60)

